<script setup lang="ts">
import { ArrowRight, UserRound } from '@lucide/vue'
const name=ref(''),email=ref(''),password=ref(''),confirm=ref(''),busy=ref(false),errorMessage=ref('')
async function register(){errorMessage.value='';if(password.value!==confirm.value){errorMessage.value='Les mots de passe ne correspondent pas.';return}busy.value=true;try{await $fetch('/api/auth/sign-up/email',{method:'POST',body:{name:name.value.trim(),email:email.value.trim().toLowerCase(),password:password.value}});await navigateTo('/mon-compte')}catch(error){const data=(error as {data?:{message?:string;statusMessage?:string}})?.data;errorMessage.value=data?.message||data?.statusMessage||'Le compte n’a pas pu être créé.'}finally{busy.value=false}}
useSeoMeta({title:'Créer un compte — Votre espace',description:'Créez un espace cliente pour retrouver vos rendez-vous.',robots:'noindex,nofollow'})
</script>
<template><div class="auth-page container-narrow"><div class="auth-card surface-card"><span class="eyebrow"><UserRound :size="14"/> Espace cliente</span><h1 class="display">Gardez vos rendez-vous à portée de main.</h1><p>Votre compte peut regrouper les réservations liées après que vous les ayez réclamées avec un lien invité sécurisé.</p><form @submit.prevent="register"><label class="form-field"><span>Nom affiché</span><input v-model="name" class="form-control" autocomplete="name" required minlength="2" maxlength="120"></label><label class="form-field"><span>Adresse e-mail</span><input v-model="email" class="form-control" type="email" autocomplete="email" required maxlength="254"></label><label class="form-field"><span>Mot de passe (8 caractères minimum)</span><input v-model="password" class="form-control" type="password" autocomplete="new-password" required minlength="8"></label><label class="form-field"><span>Confirmer le mot de passe</span><input v-model="confirm" class="form-control" type="password" autocomplete="new-password" required minlength="8"></label><button class="btn btn-primary" type="submit" :disabled="busy">{{busy?'Création…':'Créer mon compte'}} <ArrowRight :size="15"/></button><p v-if="errorMessage" class="auth-error" role="alert">{{errorMessage}}</p></form><p class="account-hint">La connexion et la réservation invitée restent indépendantes. Un compte n’accède jamais à un rendez-vous sans liaison sécurisée.</p><NuxtLink class="auth-link" to="/connexion">J’ai déjà un compte</NuxtLink></div></div></template>
<style scoped>.auth-page{padding:6rem 0}.auth-card{padding:clamp(1.5rem,5vw,3rem)}.auth-card h1{margin:.8rem 0;font-size:clamp(2.8rem,5vw,4.6rem)}.auth-card>p{max-width:500px;color:var(--muted);font-size:.8rem}.auth-card form{display:grid;gap:1rem;margin-top:1.5rem}.form-field{display:grid;gap:.4rem}.form-field span{font-size:.72rem;font-weight:700}.auth-error{color:#943d48;font-size:.76rem}.account-hint{margin:1rem 0;color:var(--muted);font-size:.67rem}.auth-link{color:var(--merlot);font-size:.74rem;font-weight:700}</style>
